export async function checkout(order, deps) {
  const decision = await deps.fraud.decide(order);
  if (!decision.allowed) return { status: 'rejected' };
  const stock = await deps.inventory.reserve(order.items);
  const payment = await deps.payments.authorise(order, stock);
  return { status: payment.status };
}

